"""Desktop settings bytes generated by the TS owner validate in Python unchanged."""

import json
from pathlib import Path

import pytest
from hypothesis import given
from hypothesis import strategies as st

from vs_proto.api import ValidationError, desktop_settings, validate

_FIXTURES = Path(__file__).resolve().parents[3] / "proto/testdata/desktop/settings.json"


def test_retained_settings_fixtures_have_the_same_validated_cross_language_encoding() -> None:
    models = {
        "hosts": desktop_settings.DesktopHosts,
        "preferences": desktop_settings.DesktopPreferences,
        "recent": desktop_settings.DesktopRecent,
    }
    for fixture in json.loads(_FIXTURES.read_text()):
        encoded = bytes.fromhex(fixture["protobufHex"])
        message = models[fixture["kind"]].from_binary(encoded)
        validate(message)
        if "retainedProtobufHex" in fixture:
            retained = desktop_settings.RetainedDesktopHosts.from_binary(
                bytes.fromhex(fixture["retainedProtobufHex"])
            )
            validate(retained)
            current = desktop_settings.DesktopHosts(
                version=retained.version,
                hosts={
                    key: desktop_settings.DesktopHostSettings(checkout=value.checkout)
                    for key, value in retained.hosts.items()
                },
            )
            assert current == message
        assert models[fixture["kind"]].from_binary(message.to_binary()) == message, fixture["id"]


@given(st.integers(min_value=0, max_value=2**32 - 1).filter(lambda version: version != 1))
def test_desktop_settings_refuse_unsupported_versions(version: int) -> None:
    message = desktop_settings.DesktopHosts(version=version)
    with pytest.raises(ValidationError):
        validate(message)


@pytest.mark.parametrize("key", ["ssh:-option", "ssh:bad host", "unknown", "ssh:"])
def test_desktop_settings_refuse_invalid_host_keys(key: str) -> None:
    message = desktop_settings.DesktopHosts(
        version=1, hosts={key: desktop_settings.DesktopHostSettings(checkout="/project")}
    )
    with pytest.raises(ValidationError):
        validate(message)
